<script lang="ts">let { data } = $props();</script><h2>Registrations</h2><form method="GET"><input name="q" placeholder="Event or participant" value={data.q} /><select name="status" value={data.status}><option value="">All statuses</option><option>confirmed</option><option>pending</option><option>cancelled</option></select><button>Filter</button></form><table><thead><tr><th>Participant</th><th>Event</th><th>Status</th><th>Registered</th></tr></thead><tbody>{#each data.rows as row}<tr><td>{row.name ?? 'Unnamed'}</td><td>{row.event}</td><td>{row.status}</td><td>{new Date(row.createdAt).toLocaleString()}</td></tr>{/each}</tbody></table>
